#include <bits/stdc++.h>
using namespace std;

long long C[777][777];

int r, c;
long long total;
long long min_diff = (long long)1e18, min_z = -1;

void search(long long x, long long y, int v1, int v2) {
    long long diff = abs(x - y);
    if (min_diff <= 1 || diff - C[v1][r] * C[v2][r] >= min_diff) {
        return;
    }
    if (v1 == r - 1 && v2 == r - 1) {
        long long current_diff = abs(x - y);
        if (current_diff < min_diff) {
            min_diff = current_diff;
            min_z = x;
        }
        return;
    }
    if (v1 >= r) {
        long long delta1 = C[v1][r] - C[v1 - 1][r];
        long long sum2 = C[v2][r];
        search(x, y + delta1 * sum2, v1 - 1, v2);
    }
    if (v2 >= r) {
        long long sum1 = C[v1][r];
        long long delta2 = C[v2][r] - C[v2 - 1][r];
        search(x + sum1 * delta2, y, v1, v2 - 1);
    }
}

char s[12345];
int countA[12345], countB[12345];
map<long long, long long> memo_map;

long long recurse(long long x, long long y, int v1, int v2) {
    long long state_id = x * 10000 + v1 * 100 + v2;
    if (memo_map.count(state_id)) {
        return memo_map[state_id];
    }
    long long &res = memo_map[state_id];
    long long diff = abs(x - y);
    if (diff - C[v1][r] * C[v2][r] > min_diff) {
        return res = 0;
    }
    if (v1 < r || v2 < r) {
        if (v1 >= countA[v1 + v2] && v2 >= countB[v1 + v2]) {
            int sum = v1 + v2;
            v1 -= countA[sum];
            v2 -= countB[sum];
            return res = C[v1 + v2][v1];
        }
        return res = 0;
    }
    res = 0;
    char ch = s[v1 + v2 - 1];
    if (ch != 'B') {
        long long delta1 = C[v1][r] - C[v1 - 1][r];
        long long sum2 = C[v2][r];
        res += recurse(x, y + delta1 * sum2, v1 - 1, v2);
    }
    if (ch != 'A') {
        long long sum1 = C[v1][r];
        long long delta2 = C[v2][r] - C[v2 - 1][r];
        res += recurse(x + sum1 * delta2, y, v1, v2 - 1);
    }
    return res;
}

int main() {
    scanf("%d %d", &r, &c);
    for (int i = 0; i <= 2 * (r + c); i++) {
        for (int j = 0; j <= 2 * (r + c); j++) {
            if (j == 0) C[i][j] = 1; else
            if (i == 0) C[i][j] = 0;
            else C[i][j] = C[i - 1][j] + C[i - 1][j - 1];
        }
    }
    total = C[r + c][r] * C[r + c][r];
    {
        long long x = 0, y = 0;
        int v1 = r + c, v2 = r + c;
        while (v1 >= r && v2 >= r) {
            if (x > y) {
                long long delta1 = C[v1][r] - C[v1 - 1][r];
                long long sum2 = C[v2][r];
                y += delta1 * sum2;
                v1--;
            } else {
                long long sum1 = C[v1][r];
                long long delta2 = C[v2][r] - C[v2 - 1][r];
                x += sum1 * delta2;
                v2--;
            }
        }
        min_diff = abs(x - y);
    }
    search(0, 0, r + c, r + c);
    scanf("%s", s);
    countA[0] = countB[0] = 0;
    for (int i = 0; i < 2 * (r + c); i++) {
        countA[i + 1] = countA[i] + (s[i] == 'A');
        countB[i + 1] = countB[i] + (s[i] == 'B');
    }
    long long answer2 = recurse(0, 0, r + c, r + c);
    cout << answer2 << endl;
    return 0;
}
